from __future__ import annotations
import ctypes,gc,json,os,platform,signal,threading,time,tracemalloc
from collections import Counter
from pathlib import Path
OUT=Path('/diag');lock=threading.Lock();baseline=None;marker_count=0
tracemalloc.start(5)
def metrics():
 fields={}
 for line in Path('/proc/self/status').read_text().splitlines():
  key,_,value=line.partition(':')
  if key in ['VmRSS','RssAnon','RssFile','Threads']:fields[key]=int(value.strip().split()[0])*(1 if key=='Threads' else 1024)
 current,peak=tracemalloc.get_traced_memory()
 return {'at':time.time(),'traced_current_bytes':current,'traced_peak_bytes':peak,**fields}
def snapshot(_sig=None,_frame=None):
 global baseline,marker_count
 with lock:
  before=metrics();collected=gc.collect();after=metrics();snap=tracemalloc.take_snapshot()
  result={'marker':marker_count,'before_gc':before,'after_gc':after,'gc_collected':collected,'tracked_objects':len(gc.get_objects())}
  if baseline is None:baseline=snap
  else:
   differences=snap.compare_to(baseline,'lineno')
   result['net_traced_size_diff_bytes']=sum(s.size_diff for s in differences)
   result['top_growth']=[{'location':str(s.traceback[0]).replace('/tmp/venv','<venv>').replace('/repo','<repository>'),'bytes':s.size_diff,'count':s.count_diff} for s in differences[:25]]
  (OUT/f'snapshot-{marker_count:02d}.json').write_text(json.dumps(result,indent=2));marker_count+=1

def trim(_sig=None,_frame=None):
 before=metrics();libc=ctypes.CDLL(None);fn=libc.malloc_trim;fn.argtypes=[ctypes.c_size_t];fn.restype=ctypes.c_int
 code=fn(0);after=metrics();(OUT/'malloc-trim.json').write_text(json.dumps({'before':before,'after':after,'return':code},indent=2))
signal.signal(signal.SIGUSR1,snapshot);signal.signal(signal.SIGUSR2,trim)
(OUT/'environment.json').write_text(json.dumps({'python':platform.python_version(),'machine':platform.machine(),'libc':platform.libc_ver(),'platform':platform.system()},indent=2))
def monitor():
 while True:
  with (OUT/'periodic.jsonl').open('a') as f:f.write(json.dumps(metrics())+'\n')
  time.sleep(10)
threading.Thread(target=monitor,daemon=True).start()
from growwise.api.secure_entry import run
run()

