from __future__ import annotations
import concurrent.futures,json,os,secrets,signal,socket,subprocess,time
from pathlib import Path
import httpx
OUT=Path('/diag');port=19581;token=secrets.token_hex(32)
env={**os.environ,'GROWWISE_DATA_DIR':'/tmp/probe-data','GROWWISE_API_HOST':'127.0.0.1','GROWWISE_API_PORT':str(port),'GROWWISE_SESSION_TOKEN':token,'GROWWISE_LLM_FEATURES_ENABLED':'false','GROWWISE_VISION_FEATURES_ENABLED':'false','GROWWISE_EMBEDDING_FEATURES_ENABLED':'false','GROWWISE_PUBLIC_ENRICHMENT_ENABLED':'false'}
core=subprocess.Popen(['/tmp/venv/bin/python','/diag/core_probe.py'],env=env,cwd='/diag',stdout=subprocess.DEVNULL,stderr=(OUT/'core.stderr').open('w'))
client=httpx.Client(base_url=f'http://127.0.0.1:{port}',headers={'Authorization':'Bearer '+token},timeout=60)
def req(path,body=None):
 response=client.get(path) if body is None else client.post(path,json=body)
 response.raise_for_status();return response.json()
def mark(n):
 os.kill(core.pid,signal.SIGUSR1)
 deadline=time.time()+30
 while not (OUT/f'snapshot-{n:02d}.json').exists():
  if time.time()>deadline:raise TimeoutError('snapshot')
  time.sleep(.1)
 print(json.dumps({'event':'snapshot','number':n,**json.loads((OUT/f'snapshot-{n:02d}.json').read_text())}),flush=True)
try:
 deadline=time.time()+120
 while True:
  try:req('/health');break
  except Exception:
   if core.poll() is not None:raise RuntimeError('Core exited: '+(OUT/'core.stderr').read_text()[-3000:])
   if time.time()>deadline:raise TimeoutError('Core startup')
   time.sleep(.2)
 child=req('/v1/children',{'nickname':'합성아이','stage':'elementary'})['id']
 with concurrent.futures.ThreadPoolExecutor(max_workers=4) as pool:
  futures=[pool.submit(req,f'/v1/children/{child}/learning-records',{'kind':'other','title':f'합성 기록 {n}','summary':'민들레 씨앗의 모양과 움직임을 함께 살펴본 가상 관찰입니다. '*4,'experience_axes':['exploration']}) for n in range(1000)]
  for f in futures:f.result()
 routes=[f'/v1/children/{child}/learning-records',f'/v1/resources?child_id={child}',f'/v1/children/{child}/photo-records',f'/v1/children/{child}/conversations','/v1/admin/backups',f'/v1/children/{child}/growth-map',f'/v1/children/{child}/learning-wiki']
 start=time.time()
 with concurrent.futures.ThreadPoolExecutor(max_workers=6) as pool:
  for cycle in range(153):
   for f in [pool.submit(req,path) for path in routes]:f.result()
   if cycle in [2,27,52,102,152]:
    time.sleep(.5);mark([2,27,52,102,152].index(cycle))
    print(json.dumps({'event':'progress','cycles':cycle+1,'seconds':time.time()-start}),flush=True)
 os.kill(core.pid,signal.SIGUSR2);time.sleep(2)
 print('TRIM', (OUT/'malloc-trim.json').read_text(),flush=True)
finally:
 core.terminate()
 try:core.wait(timeout=10)
 except subprocess.TimeoutExpired:core.kill();core.wait()
 client.close()

